var AI_LIMITS = { ask: 30, civics: 200, interview: 100, other: 50 };
var AI_LIMIT_MESSAGE = "You've used today's AI help. Try again tomorrow.";
function languageName(code) {
  const label = LANGUAGES.find((l) => l.value === code)?.label || "English";
  return label.match(/\(([^)]+)\)/)?.[1] || label;
}
